import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Picks the best way to get close to a destination: a teleport spell you can cast, a teleport
 * item you own (inventory, worn, or seen in your bank), or a fairy ring. Also points out a
 * teleport item you don't have yet if it would land much closer.
 * Call on the client thread.
 */
final class TeleportFinder
{
	enum Kind
	{
		SPELL,
		ITEM,
		FAIRY_RING,
		/** Jewellery box in a house; the note holds the tier (1 basic, 2 fancy, 3 ornate). */
		POH_BOX,
		POH_SPIRIT_TREE,
		/** Portal nexus destinations: only suggested through max houses. */
		POH_PORTAL
	}

	@Getter
	static final class Teleport
	{
		private final Kind kind;
		private final String name;
		private final WorldPoint landing;
		private final int[] itemIds;
		private final Map<Skill, Integer> skills = new LinkedHashMap<>();
		private final List<String> quests = new ArrayList<>();
		private final String varbits;
		private final String varps;
		private final String note;
		/** Spellbook the spell is on (SPELLBOOK varbit value), or -1. */
		private final int spellbook;

		Teleport(Kind kind, String name, int x, int y, int plane, String items, String skillReqs, String questReqs,
			String varbits, String varps, String note)
		{
			this.kind = kind;
			this.name = name;
			this.landing = new WorldPoint(x, y, plane);
			this.itemIds = items.isEmpty() ? new int[0] : java.util.Arrays.stream(items.split(",")).mapToInt(Integer::parseInt).toArray();
			for (String s : skillReqs.split(","))
			{
				if (!s.isEmpty())
				{
					String[] kv = s.split(":");
					try
					{
						skills.put(Skill.valueOf(kv[0]), Integer.parseInt(kv[1]));
					}
					catch (IllegalArgumentException ignored)
					{
						// unknown skill name: ignore the requirement
					}
				}
			}
			for (String q : questReqs.split(","))
			{
				if (!q.isEmpty())
				{
					quests.add(q);
				}
			}
			int book = -1;
			StringBuilder other = new StringBuilder();
			for (String tok : varbits.split(";"))
			{
				if (tok.startsWith(VarbitID.SPELLBOOK + "="))
				{
					book = Integer.parseInt(tok.substring(tok.indexOf('=') + 1));
				}
				else if (!tok.isEmpty())
				{
					other.append(other.length() > 0 ? ";" : "").append(tok);
				}
			}
			this.spellbook = book;
			this.varbits = other.toString();
			this.varps = varps;
			this.note = note;
		}
	}

	private static final String[] SPELLBOOKS = {"Standard", "Ancient", "Lunar", "Arceuus"};
	/** Extra "tiles" for a fairy ring, since you need to reach a ring first. */
	private static final int FAIRY_RING_PENALTY = 15;
	/** Only suggest a teleport if it saves at least this many tiles over walking. */
	private static final int MIN_SAVING = 20;
	/** Extra "tiles" for using your own house (teleport there first). */
	private static final int OWN_HOUSE_PENALTY = 5;
	/** Extra "tiles" for a max house (hop to W330, go to a house portal, join a house). */
	private static final int MAX_HOUSE_PENALTY = 25;

	// What the player's own house has, from the plugin settings
	private int boxTier;
	private boolean houseSpiritTree;
	private boolean houseFairyRing;
	private boolean maxHouses;

	private final List<Teleport> teleports;
	private final Set<Integer> teleportItemIds = new HashSet<>();
	private final Set<Integer> inventory = new HashSet<>();
	private final Set<Integer> worn = new HashSet<>();
	private final Set<Integer> bank = new HashSet<>();

	TeleportFinder(List<Teleport> teleports)
	{
		this.teleports = teleports;
		for (Teleport t : teleports)
		{
			for (int id : t.getItemIds())
			{
				teleportItemIds.add(id);
			}
		}
	}

	/** House settings: jewellery box tier (0 none .. 3 ornate), spirit tree, fairy ring, use max houses. */
	void setHouse(int boxTier, boolean spiritTree, boolean fairyRing, boolean useMaxHouses)
	{
		this.boxTier = boxTier;
		this.houseSpiritTree = spiritTree;
		this.houseFairyRing = fairyRing;
		this.maxHouses = useMaxHouses;
	}

	/** Refresh inventory and worn items from the client. */
	void refreshCarried(Client client)
	{
		fill(inventory, client.getItemContainer(InventoryID.INV));
		fill(worn, client.getItemContainer(InventoryID.WORN));
	}

	/** Remember which teleport items are in the bank. Returns the ids as text to save. */
	String updateBank(ItemContainer container)
	{
		fill(bank, container);
		StringBuilder sb = new StringBuilder();
		for (int id : bank)
		{
			sb.append(sb.length() > 0 ? "," : "").append(id);
		}
		return sb.toString();
	}

	/** Load bank teleport items saved from an earlier session. */
	void loadBank(String saved)
	{
		bank.clear();
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		for (String s : saved.split(","))
		{
			try
			{
				bank.add(Integer.parseInt(s));
			}
			catch (NumberFormatException ignored)
			{
				// skip bad entries
			}
		}
	}

	/**
	 * A one-line suggestion for getting to dest, or null if walking is as good.
	 *
	 * @param questState state of a quest, by RuneLite Quest enum name
	 */
	String suggest(Client client, WorldPoint dest, Function<String, QuestState> questState)
	{
		WorldPoint player = client.getLocalPlayer().getWorldLocation();
		int walk = distance(player, dest);
		int currentBook = client.getVarbitValue(VarbitID.SPELLBOOK);
		boolean fairyRings = canUseFairyRings(client, questState);

		Teleport best = null;
		int bestScore = Integer.MAX_VALUE;
		Teleport betterUnowned = null;
		int unownedScore = Integer.MAX_VALUE;
		Teleport otherBook = null;
		int otherBookScore = Integer.MAX_VALUE;
		boolean bestViaMaxHouse = false;

		for (Teleport t : teleports)
		{
			if (!requirementsMet(client, t, questState))
			{
				continue;
			}
			int score = distance(t.getLanding(), dest);
			boolean viaMaxHouse = false;
			switch (t.getKind())
			{
				case SPELL:
					if (t.getSpellbook() != -1 && t.getSpellbook() != currentBook)
					{
						if (score < otherBookScore)
						{
							otherBookScore = score;
							otherBook = t;
						}
						continue;
					}
					break;
				case ITEM:
					if (!owns(t))
					{
						if (isBuyable(t) && score < unownedScore)
						{
							unownedScore = score;
							betterUnowned = t;
						}
						continue;
					}
					break;
				case FAIRY_RING:
					if (!fairyRings)
					{
						continue;
					}
					score += houseFairyRing ? OWN_HOUSE_PENALTY : FAIRY_RING_PENALTY;
					break;
				case POH_BOX:
				{
					int tier = t.getNote().isEmpty() ? 3 : Integer.parseInt(t.getNote());
					if (tier <= boxTier)
					{
						score += OWN_HOUSE_PENALTY;
					}
					else if (maxHouses)
					{
						score += MAX_HOUSE_PENALTY;
						viaMaxHouse = true;
					}
					else
					{
						continue;
					}
					break;
				}
				case POH_SPIRIT_TREE:
					if (houseSpiritTree)
					{
						score += OWN_HOUSE_PENALTY;
					}
					else if (maxHouses)
					{
						score += MAX_HOUSE_PENALTY;
						viaMaxHouse = true;
					}
					else
					{
						continue;
					}
					break;
				case POH_PORTAL:
					if (!maxHouses)
					{
						continue;
					}
					score += MAX_HOUSE_PENALTY;
					viaMaxHouse = true;
					break;
			}
			if (score < bestScore)
			{
				bestScore = score;
				best = t;
				bestViaMaxHouse = viaMaxHouse;
			}
		}

		StringBuilder out = new StringBuilder();
		if (best != null && bestScore + MIN_SAVING < walk)
		{
			if (bestViaMaxHouse)
			{
				out.append("Max house on W330 (house advert board) -> ");
			}
			else if (best.getKind() == Kind.POH_BOX || best.getKind() == Kind.POH_SPIRIT_TREE
				|| (best.getKind() == Kind.FAIRY_RING && houseFairyRing))
			{
				out.append("House teleport -> ");
			}
			out.append(describe(best)).append(" (lands ").append(distance(best.getLanding(), dest)).append(" tiles away)");
		}
		if (betterUnowned != null && unownedScore + MIN_SAVING < Math.min(walk, bestScore))
		{
			String item = baseName(betterUnowned);
			out.append(out.length() > 0 ? ". Faster: buy " : "Buy ").append(article(item)).append(' ').append(item)
				.append(" at the GE (");
			if (!placeName(betterUnowned).equals(item))
			{
				out.append(placeName(betterUnowned)).append(", ");
			}
			out.append("lands ").append(unownedScore).append(" tiles away)");
		}
		if (out.length() == 0 && otherBook != null && otherBookScore + MIN_SAVING < walk && otherBook.getSpellbook() < SPELLBOOKS.length)
		{
			out.append(otherBook.getName()).append(" on the ").append(SPELLBOOKS[otherBook.getSpellbook()])
				.append(" spellbook (lands ").append(otherBookScore).append(" tiles away)");
		}
		return out.length() == 0 ? null : out.toString();
	}

	private boolean requirementsMet(Client client, Teleport t, Function<String, QuestState> questState)
	{
		for (Map.Entry<Skill, Integer> e : t.getSkills().entrySet())
		{
			if (client.getRealSkillLevel(e.getKey()) < e.getValue())
			{
				return false;
			}
		}
		for (String q : t.getQuests())
		{
			if (questState.apply(q) != QuestState.FINISHED)
			{
				return false;
			}
		}
		return checkVars(t.getVarbits(), client, true) && checkVars(t.getVarps(), client, false);
	}

	/** "id=value;id>value;id<value" against varbits (or varps). */
	private static boolean checkVars(String spec, Client client, boolean varbit)
	{
		if (spec == null || spec.isEmpty())
		{
			return true;
		}
		for (String tok : spec.split(";"))
		{
			int op = Math.max(tok.indexOf('='), Math.max(tok.indexOf('>'), tok.indexOf('<')));
			if (op <= 0)
			{
				continue;
			}
			int id = Integer.parseInt(tok.substring(0, op));
			int want = Integer.parseInt(tok.substring(op + 1));
			int have = varbit ? client.getVarbitValue(id) : client.getVarpValue(id);
			char c = tok.charAt(op);
			if ((c == '=' && have != want) || (c == '>' && have <= want) || (c == '<' && have >= want))
			{
				return false;
			}
		}
		return true;
	}

	private boolean canUseFairyRings(Client client, Function<String, QuestState> questState)
	{
		if (questState.apply("FAIRYTALE_II__CURE_A_QUEEN") == QuestState.NOT_STARTED)
		{
			return false;
		}
		boolean staff = has(ItemID.DRAMEN_STAFF) || has(ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF);
		return staff || client.getVarbitValue(VarbitID.LUMBRIDGE_ELITE_REWARD) >= 1;
	}

	private boolean owns(Teleport t)
	{
		for (int id : t.getItemIds())
		{
			if (has(id))
			{
				return true;
			}
		}
		return false;
	}

	private boolean has(int id)
	{
		return inventory.contains(id) || worn.contains(id) || bank.contains(id);
	}

	private void fill(Set<Integer> set, ItemContainer container)
	{
		if (container == null)
		{
			return;
		}
		set.clear();
		for (Item item : container.getItems())
		{
			if (teleportItemIds.contains(item.getId()) || item.getId() == ItemID.DRAMEN_STAFF
				|| item.getId() == ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF)
			{
				set.add(item.getId());
			}
		}
	}

	private static String describe(Teleport t)
	{
		switch (t.getKind())
		{
			case SPELL:
				return "Cast " + t.getName() + (t.getNote().isEmpty() ? "" : " [" + t.getNote() + "]");
			case FAIRY_RING:
			case POH_PORTAL:
				return t.getName();
			default:
				return "Use " + baseName(t) + " -> " + placeName(t);
		}
	}

	/**
	 * Common teleport jewellery, tablets and scrolls that can be bought at the Grand Exchange.
	 * Quest and diary rewards (cloaks, seed pods, etc.) are left out of "buy" suggestions.
	 */
	private static boolean isBuyable(Teleport t)
	{
		String n = baseName(t).toLowerCase();
		return n.contains("necklace") || n.contains("ring of dueling") || n.contains("amulet of glory")
			|| n.contains("combat bracelet") || n.contains("ring of wealth") || n.contains("pendant")
			|| n.contains("burning amulet") || n.contains("slayer ring") || n.contains("tablet")
			|| n.contains("teleport scroll") || n.endsWith(" teleport");
	}

	private static String article(String word)
	{
		return "aeiouAEIOU".indexOf(word.charAt(0)) >= 0 ? "an" : "a";
	}

	/** "Games necklace: Burthorpe" -> "Games necklace". */
	private static String baseName(Teleport t)
	{
		int i = t.getName().indexOf(':');
		return i > 0 ? t.getName().substring(0, i).trim() : t.getName();
	}

	/** "Games necklace: Burthorpe" -> "Burthorpe". */
	private static String placeName(Teleport t)
	{
		int i = t.getName().indexOf(':');
		return i > 0 ? t.getName().substring(i + 1).trim() : t.getName();
	}

	/** Tiles between two points; different planes count a little extra. */
	private static int distance(WorldPoint a, WorldPoint b)
	{
		int d = Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY()));
		return a.getPlane() == b.getPlane() ? d : d + 5;
	}
}

package com.zerotomax;

import java.awt.Color;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

@ConfigGroup(ZeroToMaxConfig.GROUP)
public interface ZeroToMaxConfig extends Config
{
	String GROUP = "zerotomax";

	enum TrainingStyle
	{
		FASTEST_XP("Fastest XP"),
		CHILL_AFK("Chill / AFK"),
		MINIGAME("Minigames");

		private final String label;

		TrainingStyle(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "GPS & Display",
		description = "Overlay line and training style",
		position = 0
	)
	String displaySection = "displaySection";

	@ConfigItem(
		keyName = "trainingStyle",
		name = "Training Style",
		description = "Fastest XP, chill AFK methods, or minigames",
		section = displaySection,
		position = 1
	)
	default TrainingStyle trainingStyle()
	{
		return TrainingStyle.FASTEST_XP;
	}

	@ConfigItem(
		keyName = "cycleStyleHotkey",
		name = "Cycle Style Hotkey",
		description = "Press to switch between training styles",
		section = displaySection,
		position = 2
	)
	default Keybind cycleStyleHotkey()
	{
		return new Keybind(KeyEvent.VK_F12, 0);
	}

	@ConfigItem(
		keyName = "drawGroundPath",
		name = "Draw GPS Line",
		description = "Draws a line to your current objective",
		section = displaySection,
		position = 3
	)
	default boolean drawGroundPath()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useShortestPath",
		name = "Use Shortest Path for the route",
		description = "Send your destination to the Shortest Path plugin (install it from the Plugin Hub) so it draws a walkable route. Turn off to use the simple straight line instead.",
		section = displaySection,
		position = 5
	)
	default boolean useShortestPath()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "pathColor",
		name = "GPS Line Color",
		description = "Color of the GPS line",
		section = displaySection,
		position = 4
	)
	default Color pathColor()
	{
		return Color.CYAN;
	}

	/** A skill to focus on, or OFF to let the guide pick. Names match net.runelite.api.Skill. */
	enum FocusSkill
	{
		OFF("Off (guide picks)"),
		ATTACK("Attack"),
		STRENGTH("Strength"),
		DEFENCE("Defence"),
		RANGED("Ranged"),
		PRAYER("Prayer"),
		MAGIC("Magic"),
		RUNECRAFT("Runecraft"),
		CONSTRUCTION("Construction"),
		HITPOINTS("Hitpoints"),
		AGILITY("Agility"),
		HERBLORE("Herblore"),
		THIEVING("Thieving"),
		CRAFTING("Crafting"),
		FLETCHING("Fletching"),
		SLAYER("Slayer"),
		HUNTER("Hunter"),
		MINING("Mining"),
		SMITHING("Smithing"),
		FISHING("Fishing"),
		COOKING("Cooking"),
		FIREMAKING("Firemaking"),
		WOODCUTTING("Woodcutting"),
		FARMING("Farming"),
		SAILING("Sailing");

		private final String label;

		FocusSkill(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum JewelleryBox
	{
		NONE("None"),
		BASIC("Basic"),
		FANCY("Fancy"),
		ORNATE("Ornate");

		private final String label;

		JewelleryBox(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Your house (POH)",
		description = "What your house has, so teleport suggestions can use it",
		position = 20
	)
	String houseSection = "houseSection";

	@ConfigItem(
		keyName = "jewelleryBox",
		name = "Jewellery box",
		description = "The jewellery box in your house",
		section = houseSection,
		position = 21
	)
	default JewelleryBox jewelleryBox()
	{
		return JewelleryBox.NONE;
	}

	@ConfigItem(
		keyName = "houseSpiritTree",
		name = "Spirit tree in house",
		description = "Your house has a spirit tree",
		section = houseSection,
		position = 22
	)
	default boolean houseSpiritTree()
	{
		return false;
	}

	@ConfigItem(
		keyName = "houseFairyRing",
		name = "Fairy ring in house",
		description = "Your house has a fairy ring",
		section = houseSection,
		position = 23
	)
	default boolean houseFairyRing()
	{
		return false;
	}

	@ConfigItem(
		keyName = "useMaxHouses",
		name = "Suggest max houses (W330)",
		description = "Suggest public max houses on world 330 (join one from the house advertisement board next to any house portal) when their portals, jewellery box or spirit tree get you closer",
		section = houseSection,
		position = 24
	)
	default boolean useMaxHouses()
	{
		return true;
	}

	@ConfigSection(
		name = "Goals",
		description = "What the guide plans for you",
		position = 10
	)
	String goalsSection = "goalsSection";

	@ConfigItem(
		keyName = "focusSkill",
		name = "Train this skill",
		description = "Pick a skill and the guide shows the best way to train it to 99, using your training style. Overrides quests and diaries until you set it back to Off.",
		section = goalsSection,
		position = 9
	)
	default FocusSkill focusSkill()
	{
		return FocusSkill.OFF;
	}

	@ConfigItem(
		keyName = "skillsOnly",
		name = "Skills only (no quests)",
		description = "Skip quests and diaries and just plan your skills to 99. Farm runs, timers, teleports and Slayer help still work.",
		section = goalsSection,
		position = 10
	)
	default boolean skillsOnly()
	{
		return false;
	}

	@ConfigItem(
		keyName = "includeDiaries",
		name = "Include achievement diaries",
		description = "Plan achievement diaries as well as quests",
		section = goalsSection,
		position = 11
	)
	default boolean includeDiaries()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSlayer",
		name = "Show Slayer task help",
		description = "Show your current Slayer task and the best way to do it",
		section = goalsSection,
		position = 12
	)
	default boolean showSlayer()
	{
		return true;
	}
}

package com.zerotomax;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * The in-game box. Black and white like the side panel: the step in bold white, what to do in
 * light grey, and the small stuff in dark grey. Text runs left to right so long lines wrap neatly.
 */
public class ZeroToMaxOverlay extends OverlayPanel
{
	private static final Color WHITE = Color.WHITE;
	private static final Color LIGHT = new Color(0xD2, 0xD2, 0xD2);
	private static final Color DIM = new Color(0x8C, 0x8C, 0x8C);
	private static final int WIDTH = 210;

	private final Client client;
	private final ZeroToMaxPlugin plugin;
	private final ZeroToMaxConfig config;

	@Inject
	private ZeroToMaxOverlay(Client client, ZeroToMaxPlugin plugin, ZeroToMaxConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return null;
		}

		text("ZERO TO MAX", DIM, null);
		text(plugin.getCurrentStepTitle(), WHITE, FontManager.getRunescapeBoldFont());
		text(plugin.getCurrentStepInstruction(), LIGHT, null);
		text(plugin.getGpsStatusText(), WHITE, null);

		String method = plugin.getActiveMethodName();
		if (notEmpty(method))
		{
			text(config.trainingStyle() + " · " + method + "  [" + config.cycleStyleHotkey() + "]", DIM, null);
		}

		String progress = plugin.getProgressText();
		if (notEmpty(progress))
		{
			text(progress, DIM, null);
		}

		String slayer = plugin.getSlayerText();
		if (notEmpty(slayer))
		{
			text("Slayer: " + slayer, LIGHT, null);
		}

		String farm = plugin.getFarmAlertText();
		if (notEmpty(farm))
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Farming")
				.leftColor(DIM)
				.right(farm)
				.rightColor(WHITE)
				.build());
		}

		String account = plugin.getAccountStatusText();
		if (notEmpty(account))
		{
			// "Quests 94/184 ... QP 169" on one line, then "Diaries 0/48" under it, so nothing wraps
			String[] parts = account.split(" \\| ");
			if (parts.length >= 2)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(parts[0])
					.leftColor(DIM)
					.right(parts[parts.length - 1])
					.rightColor(DIM)
					.build());
				for (int i = 1; i < parts.length - 1; i++)
				{
					text(parts[i], DIM, null);
				}
			}
			else
			{
				text(account, DIM, null);
			}
		}

		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		return super.render(graphics);
	}

	/** One left-aligned line (wraps when long). */
	private void text(String value, Color color, Font font)
	{
		if (!notEmpty(value))
		{
			return;
		}
		LineComponent.LineComponentBuilder b = LineComponent.builder()
			.left(value)
			.leftColor(color);
		if (font != null)
		{
			b.leftFont(font);
		}
		panelComponent.getChildren().add(b.build());
	}

	private static boolean notEmpty(String s)
	{
		return s != null && !s.isEmpty();
	}
}

package com.zerotomax;

import com.zerotomax.farming.FarmTracker;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel. Black and white: white for what matters now, grey for everything else.
 * Every section can be folded away by clicking its title.
 */
@Singleton
public class ZeroToMaxPanel extends PluginPanel
{
	private static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
	private static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
	private static final Color LINE = new Color(0x3A, 0x3A, 0x3A);
	private static final Color TEXT = Color.WHITE;
	private static final Color MUTED = new Color(0x9A, 0x9A, 0x9A);
	private static final Color CHIP = new Color(0x2A, 0x2A, 0x2A);
	private static final Color CHIP_HOVER = new Color(0x3C, 0x3C, 0x3C);
	private static final String WHITE_HEX = "#ffffff";
	private static final String MUTED_HEX = "#9a9a9a";
	private static final String DIM_HEX = "#6a6a6a";
	private static final int TEXT_WIDTH = 135;

	private final ZeroToMaxConfig config;

	private final JLabel objectiveLabel = body();
	private final JLabel timersLabel = body();
	private final JLabel runStatusLabel = body();
	private final JLabel checklistLabel = body();
	private final JLabel slayerLabel = body();
	private final JLabel roadmapLabel = body();
	private final Map<FarmTracker.RunType, RunChip> chips = new EnumMap<>(FarmTracker.RunType.class);

	/** Set by the plugin. Called on the Swing thread with the run to start, or null to stop. */
	private volatile Consumer<FarmTracker.RunType> runListener;

	@Inject
	ZeroToMaxPanel(ZeroToMaxConfig config)
	{
		super();
		this.config = config;

		setLayout(new BorderLayout());
		setBackground(BACKGROUND);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setBackground(BACKGROUND);

		container.add(header());
		container.add(gap(10));

		container.add(section("Current objective", objectiveLabel));
		container.add(gap(8));
		container.add(section("Run timers", timersLabel));
		container.add(gap(8));

		JPanel runBody = column();
		JPanel grid = new JPanel(new GridLayout(4, 2, 4, 4));
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		addChip(grid, "Herbs", FarmTracker.RunType.HERB);
		addChip(grid, "Trees", FarmTracker.RunType.TREE);
		addChip(grid, "Fruit trees", FarmTracker.RunType.FRUIT_TREE);
		addChip(grid, "Hardwood", FarmTracker.RunType.HARDWOOD);
		addChip(grid, "Calquat", FarmTracker.RunType.CALQUAT);
		addChip(grid, "Spirit trees", FarmTracker.RunType.SPIRIT_TREE);
		addChip(grid, "Birdhouses", FarmTracker.RunType.BIRDHOUSE);
		grid.add(new RunChip("Stop", null));
		runBody.add(grid);
		runBody.add(gap(8));
		runBody.add(runStatusLabel);
		runBody.add(gap(6));
		runBody.add(checklistLabel);
		container.add(section("Farm run GPS", runBody));
		container.add(gap(8));

		container.add(section("Slayer task", slayerLabel));
		container.add(gap(8));
		container.add(section("Roadmap", roadmapLabel));

		add(container, BorderLayout.NORTH);
	}

	void setRunListener(Consumer<FarmTracker.RunType> listener)
	{
		this.runListener = listener;
	}

	/** Safe to call from any thread. */
	public void update(String title, String method, String instruction, String teleport, String progress)
	{
		StringBuilder sb = open();
		sb.append("<b><font color='").append(WHITE_HEX).append("'>").append(escape(title)).append("</font></b><br/>");
		String style = config.trainingStyle().toString()
			+ (method == null || method.isEmpty() ? "" : " · " + method);
		row(sb, "Style", style);
		row(sb, "Do", instruction);
		row(sb, "Teleport", teleport);
		if (progress != null && !progress.isEmpty())
		{
			row(sb, "Progress", progress);
		}
		String html = close(sb);
		SwingUtilities.invokeLater(() -> objectiveLabel.setText(html));
	}

	public void setSlayer(List<String> lines)
	{
		StringBuilder sb = open();
		boolean first = true;
		for (String line : lines)
		{
			int colon = line.indexOf(": ");
			if (first)
			{
				sb.append("<b><font color='").append(WHITE_HEX).append("'>").append(escape(line)).append("</font></b><br/>");
				first = false;
			}
			else if (colon > 0 && colon < 16)
			{
				row(sb, line.substring(0, colon), line.substring(colon + 2));
			}
			else
			{
				sb.append(escape(line)).append("<br/>");
			}
		}
		String html = close(sb);
		SwingUtilities.invokeLater(() -> slayerLabel.setText(html));
	}

	public void setRoadmap(List<String> steps)
	{
		StringBuilder sb = open();
		int i = 1;
		for (String step : steps)
		{
			String color = i == 1 ? WHITE_HEX : MUTED_HEX;
			sb.append("<font color='").append(DIM_HEX).append("'>").append(i).append("&nbsp;&nbsp;</font>")
				.append("<font color='").append(color).append("'>").append(escape(step)).append("</font><br/>");
			i++;
		}
		String html = close(sb);
		SwingUtilities.invokeLater(() -> roadmapLabel.setText(html));
	}

	/** Safe to call from any thread. Timers are "Name: value" lines. */
	public void setFarming(FarmTracker.RunType active, List<String> timers, String runStatus,
		String checklistTitle, List<String> checklist)
	{
		StringBuilder t = new StringBuilder("<html><table width='" + (TEXT_WIDTH + 20) + "' cellpadding='1' cellspacing='0'>");
		for (String timer : timers)
		{
			int colon = timer.indexOf(": ");
			String name = colon > 0 ? timer.substring(0, colon) : timer;
			String value = colon > 0 ? timer.substring(colon + 2) : "";
			boolean ready = value.startsWith("Ready");
			t.append("<tr><td><font color='").append(ready ? WHITE_HEX : MUTED_HEX).append("'>").append(escape(name))
				.append("</font></td><td align='right'>")
				.append(ready ? "<b><font color='" + WHITE_HEX + "'>Ready</font></b>"
					: "<font color='" + DIM_HEX + "'>" + escape(value) + "</font>")
				.append("</td></tr>");
		}
		String timersHtml = t.append("</table></html>").toString();

		StringBuilder s = open();
		s.append("<font color='").append(WHITE_HEX).append("'>").append(escape(runStatus)).append("</font>");
		String statusHtml = close(s);

		StringBuilder c = open();
		c.append("<font color='").append(DIM_HEX).append("'>").append(escape(checklistTitle).toUpperCase()).append("</font><br/>");
		for (String item : checklist)
		{
			if (item.endsWith(":"))
			{
				c.append("<br/><font color='").append(DIM_HEX).append("'>").append(escape(item)).append("</font><br/>");
			}
			else
			{
				c.append("<font color='").append(DIM_HEX).append("'>–&nbsp;</font>").append(escape(item)).append("<br/>");
			}
		}
		String checklistHtml = close(c);

		SwingUtilities.invokeLater(() ->
		{
			timersLabel.setText(timersHtml);
			runStatusLabel.setText(statusHtml);
			runStatusLabel.setVisible(runStatus != null && !runStatus.isEmpty());
			checklistLabel.setText(checklistHtml);
			for (Map.Entry<FarmTracker.RunType, RunChip> e : chips.entrySet())
			{
				e.getValue().setSelected(e.getKey() == active);
			}
		});
	}

	// ------------------------------------------------------------------ building blocks

	private JPanel header()
	{
		JPanel p = column();
		JLabel title = new JLabel("ZERO TO MAX");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(TEXT);
		JLabel sub = new JLabel("Quest cape · diaries · max");
		sub.setFont(FontManager.getRunescapeSmallFont());
		sub.setForeground(MUTED);
		p.add(title);
		p.add(sub);
		p.add(gap(8));
		JPanel line = new JPanel();
		line.setBackground(LINE);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		line.setPreferredSize(new Dimension(0, 1));
		p.add(line);
		return p;
	}

	/** A card with a title you can click to fold the body away. */
	private JPanel section(String title, Component content)
	{
		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(CARD);
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 1, 1, 1, LINE),
			new EmptyBorder(8, 9, 9, 9)));

		JPanel head = new JPanel(new BorderLayout());
		head.setOpaque(false);
		head.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		JLabel name = new JLabel(title.toUpperCase());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(MUTED);
		JLabel arrow = new JLabel("−");
		arrow.setForeground(MUTED);
		head.add(name, BorderLayout.WEST);
		head.add(arrow, BorderLayout.EAST);

		JPanel bodyWrap = column();
		bodyWrap.setBorder(new EmptyBorder(6, 0, 0, 0));
		if (content instanceof JLabel)
		{
			((JLabel) content).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		bodyWrap.add(content);

		head.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				boolean show = !bodyWrap.isVisible();
				bodyWrap.setVisible(show);
				arrow.setText(show ? "−" : "+");
				card.revalidate();
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				name.setForeground(TEXT);
				arrow.setForeground(TEXT);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				name.setForeground(MUTED);
				arrow.setForeground(MUTED);
			}
		});

		card.add(head, BorderLayout.NORTH);
		card.add(bodyWrap, BorderLayout.CENTER);
		return card;
	}

	private void addChip(JPanel grid, String text, FarmTracker.RunType type)
	{
		RunChip chip = new RunChip(text, type);
		chips.put(type, chip);
		grid.add(chip);
	}

	/** Flat black-and-white button. White when its run is active. */
	private final class RunChip extends JLabel
	{
		private boolean selected;
		private boolean hover;

		RunChip(String text, FarmTracker.RunType type)
		{
			super(text, SwingConstants.CENTER);
			setOpaque(true);
			setFont(FontManager.getRunescapeSmallFont());
			setBorder(new EmptyBorder(5, 2, 5, 2));
			setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			paintState();
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					Consumer<FarmTracker.RunType> l = runListener;
					if (l != null)
					{
						l.accept(type);
					}
					for (Map.Entry<FarmTracker.RunType, RunChip> c : chips.entrySet())
					{
						c.getValue().setSelected(c.getKey() == type);
					}
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					hover = true;
					paintState();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					hover = false;
					paintState();
				}
			});
		}

		void setSelected(boolean selected)
		{
			if (this.selected != selected)
			{
				this.selected = selected;
				paintState();
			}
		}

		private void paintState()
		{
			setBackground(selected ? TEXT : hover ? CHIP_HOVER : CHIP);
			setForeground(selected ? Color.BLACK : hover ? TEXT : MUTED);
		}
	}

	private static JLabel body()
	{
		JLabel l = new JLabel();
		l.setForeground(MUTED);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel column()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	private static JPanel gap(int height)
	{
		JPanel s = new JPanel();
		s.setOpaque(false);
		s.setAlignmentX(Component.LEFT_ALIGNMENT);
		s.setPreferredSize(new Dimension(0, height));
		s.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return s;
	}

	private static StringBuilder open()
	{
		return new StringBuilder("<html><div style='width:" + TEXT_WIDTH + "px'>");
	}

	private static String close(StringBuilder sb)
	{
		return sb.append("</div></html>").toString();
	}

	/** Grey label, white value. */
	private static void row(StringBuilder sb, String label, String value)
	{
		sb.append("<font color='").append(DIM_HEX).append("'>").append(escape(label)).append("</font>&nbsp;&nbsp;")
			.append("<font color='").append(WHITE_HEX).append("'>").append(escape(value)).append("</font><br/>");
	}

	private static String escape(String s)
	{
		return s == null ? "-" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

