// Copied from RuneLite's Time Tracking plugin (net.runelite.client.plugins.timetracking.farming)
// because RuneLite keeps this class package-private. Unchanged apart from the package and imports.
package com.zerotomax.farming;

import lombok.Value;
import net.runelite.client.plugins.timetracking.farming.CropState;
import net.runelite.client.plugins.timetracking.farming.Produce;

@Value
class PatchState
{
	private final Produce produce;
	private final CropState cropState;
	private final int stage;

	int getStages()
	{
		return cropState == CropState.HARVESTABLE || cropState == CropState.FILLING ? produce.getHarvestStages() : produce.getStages();
	}

	int getTickRate()
	{
		switch (cropState)
		{
			case HARVESTABLE:
				return produce.getRegrowTickrate();
			case GROWING:
				return produce.getTickrate();
			default:
				return 0;
		}
	}
}

